options.css:
:host {
  --dashboard-bg: #000000;
  --panel-bg: #030b14;
  --panel-bg-2: #06111d;
  --panel-hover: #091725;
  --border: #14314a;
  --border-strong: #1d4d73;
  --border-muted: #10283c;
  --text-1: #f4f7fb;
  --text-2: #c8d3df;
  --text-3: #93a7ba;
  --healthy: #16d6a0;
  --healthy-bright: #32e6af;
  --warning: #ffb000;
  --warning-bright: #ffc62e;
  --critical: #ff405b;
  --critical-bright: #ff5870;
  --management: #268cff;
  --traffic-in: #22cf79;
  --traffic-out: #268cff;
  --unknown: #65788b;
  --gap: clamp(5px, 0.55vh, 10px);
  --pad: clamp(5px, 0.55vw, 10px);
  display: block;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: #000;
  color: var(--text-1);
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  color-scheme: dark;
}

*, *::before, *::after { box-sizing: border-box; }

#dashboard-stage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--dashboard-bg);
}

#dashboard-root {
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  padding: var(--pad);
  display: grid;
  grid-template-rows:
    minmax(44px, 0.68fr)
    minmax(78px, 1.15fr)
    minmax(118px, 1.72fr)
    minmax(150px, 2.25fr)
    minmax(190px, 3.25fr)
    minmax(12px, 0.16fr);
  gap: var(--gap);
  background: #000;
}

.panel,
.header,
.kpi {
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(4, 15, 25, 0.99), rgba(1, 8, 14, 0.99));
  border: 1px solid var(--border);
  border-radius: clamp(7px, 0.55vw, 11px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025), 0 4px 16px rgba(0, 0, 0, 0.22);
}

/* Header */
.header {
  display: grid;
  grid-template-columns: minmax(280px, 1fr) clamp(120px, 14vw, 220px) minmax(440px, 1fr);
  align-items: center;
  gap: clamp(8px, 0.8vw, 16px);
  padding: clamp(5px, 0.55vh, 10px) clamp(10px, 0.85vw, 18px);
}
.header-left, .header-center, .header-right, .header-text { min-width: 0; }
.header-left { justify-self: start; display: flex; align-items: center; }
.header-center { justify-self: center; display: flex; align-items: center; justify-content: center; width: 100%; height: 100%; }
.header-right { justify-self: end; display: flex; align-items: center; justify-content: flex-end; gap: clamp(4px, 0.45vw, 9px); white-space: nowrap; }
.header-title { font-size: clamp(16px, 1.25vw, 20px); line-height: 1.03; font-weight: 850; letter-spacing: 0.01em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.header-sub { display: flex; align-items: center; gap: clamp(4px, 0.35vw, 8px); margin-top: clamp(2px, 0.3vh, 5px); color: var(--text-2); font-size: clamp(8px, 0.58vw, 11px); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.status-chip { display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px; border-radius: 999px; background: rgba(22, 214, 160, 0.12); border: 1px solid rgba(22, 214, 160, 0.42); color: var(--healthy-bright); font-size: clamp(7px, 0.48vw, 9px); font-weight: 900; flex-shrink: 0; }
.status-chip::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; box-shadow: 0 0 7px currentColor; }
.status-chip.critical { color: var(--critical-bright); border-color: rgba(255,64,91,.5); background: rgba(255,64,91,.12); }
.status-chip.unknown { color: var(--unknown); border-color: rgba(101,120,139,.55); background: rgba(101,120,139,.1); }
.demo-logo { display: block; width: 100%; height: clamp(30px, 5.3vh, 55px); object-fit: contain; object-position: center; filter: drop-shadow(0 1px 2px rgba(0,0,0,.7)); }
.header-stat { min-width: clamp(64px, 5.5vw, 102px); text-align: right; padding: 2px clamp(2px, 0.3vw, 6px); }
.header-stat-label { color: var(--text-3); font-size: clamp(6.5px, 0.45vw, 8.5px); font-weight: 850; text-transform: uppercase; letter-spacing: .03em; }
.header-stat-value { margin-top: 2px; color: var(--text-1); font-family: Consolas, "SFMono-Regular", monospace; font-size: clamp(8px, 0.65vw, 12px); font-weight: 800; }
.refresh-box { height: clamp(26px, 3.4vh, 34px); display: flex; align-items: center; gap: 6px; padding: 0 clamp(6px, 0.55vw, 11px); border: 1px solid var(--border); border-radius: 999px; color: var(--text-2); font-size: clamp(7px, .5vw, 9px); font-weight: 800; }
.refresh-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--management); box-shadow: 0 0 8px rgba(38,140,255,.85); }
.overall-box { min-width: clamp(92px, 7.1vw, 128px); padding: clamp(4px, .45vh, 7px) clamp(7px, .55vw, 11px); text-align: center; border: 1px solid rgba(22,214,160,.42); border-radius: 8px; background: rgba(22,214,160,.055); }
.overall-box span { display: block; color: var(--text-3); font-size: clamp(6.5px, .43vw, 8px); font-weight: 850; text-transform: uppercase; }
.overall-box strong { display: block; margin-top: 2px; color: var(--healthy-bright); font-size: clamp(9px, .72vw, 13px); }
.overall-box.critical { border-color: rgba(255,64,91,.48); background: rgba(255,64,91,.07); }
.overall-box.critical strong { color: var(--critical-bright); }
.overall-box.unknown { border-color: rgba(101,120,139,.52); background: rgba(101,120,139,.07); }
.overall-box.unknown strong { color: #9caebe; }

/* KPI row */
.cards { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: var(--gap); min-width: 0; min-height: 0; }
.kpi { position: relative; height: 100%; padding: clamp(6px, .68vh, 11px) clamp(7px, .6vw, 12px); display: grid; grid-template-rows: auto minmax(0, 1fr) auto; }
.kpi::before { content: ""; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--border-strong); }
.kpi.green::before { background: var(--healthy); }
.kpi.blue::before { background: var(--management); }
.kpi.yellow::before { background: var(--warning); }
.kpi.state-warning::before { background: var(--warning); }
.kpi.state-critical::before { background: var(--critical); }
.kpi.state-unknown::before { background: var(--unknown); }
.kpi-top { display: flex; align-items: center; gap: clamp(5px, .45vw, 9px); min-width: 0; }
.kpi-icon {
  width: clamp(31px, 2.45vw, 44px);
  height: clamp(31px, 2.45vw, 44px);
  border: 1.5px solid currentColor;
  border-radius: clamp(8px, .62vw, 12px);
  display: grid;
  place-items: center;
  flex-shrink: 0;
  background: rgba(255,255,255,.035);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08), 0 0 12px rgba(0,0,0,.34);
}
.kpi-icon svg {
  width: 72%;
  height: 72%;
  display: block;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}
.kpi.green .kpi-icon { color: var(--healthy-bright); background: rgba(22,214,160,.09); box-shadow: inset 0 1px 0 rgba(255,255,255,.08), 0 0 12px rgba(22,214,160,.12); }
.kpi.blue .kpi-icon { color: #62afff; background: rgba(38,140,255,.10); box-shadow: inset 0 1px 0 rgba(255,255,255,.08), 0 0 12px rgba(38,140,255,.13); }
.kpi.yellow .kpi-icon { color: var(--warning-bright); background: rgba(255,176,0,.09); box-shadow: inset 0 1px 0 rgba(255,255,255,.08), 0 0 12px rgba(255,176,0,.12); }
.kpi-label { min-width: 0; color: var(--text-2); font-size: clamp(7.5px, .58vw, 11px); font-weight: 850; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.kpi-value { align-self: center; margin-left: clamp(30px, 2.5vw, 46px); color: var(--text-1); font-size: clamp(18px, 1.55vw, 31px); font-weight: 900; letter-spacing: -.025em; line-height: 1; }
.kpi-footer { min-width: 0; display: flex; align-items: end; justify-content: space-between; gap: 6px; }
.kpi-sub { min-width: 0; color: var(--text-3); font-size: clamp(6.5px, .48vw, 9px); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sparkline { min-width: 0; width: 100%; height: clamp(16px, 2.8vh, 28px); overflow: visible; }
.sparkline polyline { fill: none; stroke-width: 1.6; vector-effect: non-scaling-stroke; }
.kpi-progress { flex: 0 1 clamp(50px, 5vw, 90px); height: clamp(4px, .55vh, 7px); background: #102331; border-radius: 999px; overflow: hidden; }
.kpi-progress i { display: block; height: 100%; border-radius: inherit; background: var(--healthy); }

/* Panel headers */
.panel { display: flex; flex-direction: column; }
.panel-header, .device-caption { flex: 0 0 clamp(26px, 3.4vh, 36px); height: clamp(26px, 3.4vh, 36px); min-width: 0; display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 0 clamp(8px, .65vw, 13px); border-bottom: 1px solid var(--border-muted); }
.panel-title, .device-caption strong { color: var(--text-1); font-size: clamp(8px, .62vw, 11.5px); font-weight: 900; text-transform: uppercase; letter-spacing: .02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.panel-meta, .device-caption span { color: var(--text-3); font-size: clamp(6.5px, .48vw, 9px); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Appliance */
.device-section { min-width: 0; min-height: 0; }
.chassis { flex: 1 1 auto; min-width: 0; min-height: 0; margin: clamp(4px, .45vh, 8px); padding: clamp(6px, .7vh, 11px) clamp(8px, .75vw, 15px); display: grid; grid-template-columns: minmax(145px, 15%) minmax(0, 1fr) minmax(105px, 10%); align-items: center; gap: clamp(7px, .65vw, 13px); position: relative; overflow: hidden; border: 1px solid #a6afb5; border-radius: 7px; background: linear-gradient(180deg,#d5dadd 0%,#aab2b7 8%,#647078 23%,#3c464d 44%,#252d32 68%,#171d21 100%); box-shadow: inset 0 3px 8px rgba(255,255,255,.2), inset 0 -8px 16px rgba(0,0,0,.34), 0 7px 18px rgba(0,0,0,.42); }
.chassis::before { content: ""; position: absolute; inset: 0; pointer-events: none; background: repeating-linear-gradient(90deg, rgba(255,255,255,.025) 0 1px, rgba(0,0,0,.025) 1px 3px); }
.chassis-left, .chassis-center, .chassis-right { position: relative; z-index: 1; min-width: 0; min-height: 0; }
.chassis-left { height: 100%; display: grid; grid-template-columns: minmax(78px, 1fr) auto; align-items: center; gap: clamp(5px, .45vw, 9px); }
.device-brand { min-width: 0; height: 100%; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; }
.pa-logo-img { width: min(100%, clamp(78px, 7.2vw, 125px)); height: clamp(25px, 4.2vh, 42px); object-fit: contain; object-position: left center; filter: drop-shadow(0 1px 2px rgba(0,0,0,.58)); }
.sys-leds { margin-top: clamp(5px, .65vh, 10px); display: grid; gap: clamp(2px, .36vh, 6px); color: #f0f4f6; font-size: clamp(6px, .45vw, 8px); }
.sys-leds div { display: flex; align-items: center; gap: 6px; }
.sys-led { width: 6px; height: 6px; border-radius: 50%; background: var(--healthy); box-shadow: 0 0 6px var(--healthy); }
.service-ports { display: flex; align-items: center; justify-content: center; gap: clamp(5px, .5vw, 10px); }
.service-port { display: flex; flex-direction: column; align-items: center; gap: 4px; }
.service-label, .port-name { color: #f2f5f7; font-size: clamp(6px, .46vw, 8px); font-weight: 850; white-space: nowrap; }
.metal-port { width: clamp(36px, 3.15vw, 55px); height: clamp(39px, 5.4vh, 58px); padding: clamp(3px, .35vw, 6px); border: 1px solid #f1f3f4; border-radius: 3px; background: linear-gradient(180deg,#f1f3f4,#aab3b9 58%,#707b82); box-shadow: inset 0 1px 0 #fff,0 0 0 1px #323a40; }
.mgmt-strip { height: clamp(4px, .55vh, 7px); margin-bottom: 3px; border-radius: 1px; background: var(--management); box-shadow: 0 0 5px rgba(38,140,255,.65); }
.service-jack { height: calc(100% - 2px); position: relative; background: #020606; border: 3px solid #14191b; box-shadow: inset 0 0 9px #000; }
.metal-port.mgmt .service-jack { height: calc(100% - clamp(7px, .9vh, 10px)); }
.service-jack::after { content: ""; position: absolute; top: 2px; left: 4px; right: 4px; height: 5px; background: repeating-linear-gradient(90deg,#d6b642 0 2px,transparent 2px 4px); }
.chassis-center { display: flex; align-items: center; justify-content: center; }
.ports-grid { width: 100%; min-width: 0; display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); align-items: center; gap: clamp(3px, .42vw, 8px); }
.port-wrap { min-width: 0; display: flex; flex-direction: column; align-items: center; gap: 4px; }
.eth-frame { width: 100%; height: clamp(31px, 5.1vh, 54px); padding: clamp(3px, .35vw, 6px); position: relative; border: 2px solid var(--unknown); border-radius: 3px; background: linear-gradient(180deg,#f2f4f5,#adb5ba 57%,#717b82); box-shadow: inset 0 1px 0 #fff,0 0 0 1px #252b30; }
.eth-frame::before, .eth-frame::after { content: ""; position: absolute; top: 3px; width: clamp(4px, .45vw, 7px); height: clamp(3px, .45vh, 5px); border-radius: 1px; background: var(--unknown); }
.eth-frame::before { left: 5px; } .eth-frame::after { right: 5px; }
.eth-frame.up, .eth-frame.management { border-color: var(--healthy-bright); box-shadow: inset 0 1px 0 #fff,0 0 8px rgba(50,230,175,.58); }
.eth-frame.up::before, .eth-frame.up::after { background: var(--healthy-bright); }
.eth-frame.management { border-color: var(--management); box-shadow: inset 0 1px 0 #fff,0 0 8px rgba(38,140,255,.58); }
.eth-frame.management::before, .eth-frame.management::after { background: var(--management); }
.eth-frame.down { border-color: var(--critical-bright); box-shadow: inset 0 1px 0 #fff,0 0 8px rgba(255,88,112,.58); }
.eth-frame.down::before, .eth-frame.down::after { background: var(--critical-bright); }
.eth-frame.disabled { border-color: var(--warning-bright); box-shadow: inset 0 1px 0 #fff,0 0 8px rgba(255,198,46,.52); }
.eth-frame.disabled::before, .eth-frame.disabled::after { background: var(--warning-bright); }
.eth-frame.unknown { border-color: var(--unknown); box-shadow: inset 0 1px 0 #fff; filter: saturate(.45); }
.eth-rj { height: calc(100% - clamp(7px, 1vh, 11px)); margin-top: clamp(5px, .75vh, 8px); position: relative; background: #010504; border: 3px solid #13191b; box-shadow: inset 0 0 10px #000; }
.eth-rj::before { content: ""; position: absolute; top: 1px; left: 4px; right: 4px; height: 5px; background: repeating-linear-gradient(90deg,#c8ab43 0 2px,transparent 2px 4px); }
.chassis-right { height: 100%; display: grid; grid-template-columns: minmax(42px, 1fr) minmax(58px, 45%); align-items: center; gap: clamp(5px, .5vw, 10px); }
.device-led-panel { display: grid; gap: clamp(2px, .4vh, 6px); color: #fff; font-size: clamp(6px, .43vw, 8px); }
.device-led-panel div { display: flex; align-items: center; gap: 6px; }
.right-led { width: 7px; height: 7px; border-radius: 50%; background: var(--healthy); box-shadow: 0 0 7px var(--healthy); }
.right-led.warn { background: var(--warning); box-shadow: 0 0 7px var(--warning); }
.right-led.off { background: #45515a; box-shadow: none; }
.vent { width: 100%; height: clamp(60px, 10vh, 100px); border: 1px solid #4f5b63; border-radius: 3px; background-color: #050708; background-image: radial-gradient(#374149 34%,transparent 36%); background-size: 11px 10px; box-shadow: inset 0 0 14px #000; }

/* Monitoring */
.monitoring-row { display: grid; grid-template-columns: minmax(0, 25fr) minmax(0, 35fr) minmax(0, 40fr); gap: var(--gap); min-width: 0; min-height: 0; }
.monitoring-row > .panel { min-width: 0; min-height: 0; }
.uplinks-content { flex: 1; min-width: 0; min-height: 0; padding: clamp(3px, .45vh, 7px) clamp(6px, .55vw, 10px); display: grid; grid-template-rows: repeat(3, minmax(0, 1fr)); overflow: hidden; }
.uplink { min-width: 0; min-height: 0; display: grid; grid-template-columns: clamp(25px, 2.3vw, 36px) minmax(0,1fr) clamp(74px, 7vw, 112px); align-items: center; gap: clamp(5px, .5vw, 9px); padding: clamp(2px, .28vh, 5px) 0; border-bottom: 1px solid var(--border-muted); }
.uplink:last-child { border-bottom: 0; }
.uplink-icon { width: clamp(24px, 2.15vw, 34px); height: clamp(24px, 2.15vw, 34px); border: 1px solid rgba(38,140,255,.48); border-radius: 9px; display: grid; place-items: center; color: #55a8ff; background: rgba(38,140,255,.08); font-size: clamp(12px, .95vw, 17px); }
.uplink-name { color: var(--text-1); font-size: clamp(7.5px, .58vw, 10px); font-weight: 850; }
.uplink-alias { color: var(--text-3); font-size: clamp(6.5px, .45vw, 8px); }
.uplink-rate { margin-top: 1px; color: var(--healthy-bright); font-size: clamp(10px, .82vw, 15px); font-weight: 900; white-space: nowrap; }
.uplink-stats { min-width: 0; text-align: right; color: var(--text-2); font-size: clamp(6.3px, .43vw, 8.2px); line-height: 1.45; white-space: nowrap; }
.uplink-stats b { color: #e9f0f6; }
.mini-util { width: min(100%, 110px); height: clamp(3px, .42vh, 5px); margin-top: 3px; background: #102331; border-radius: 999px; overflow: hidden; }
.mini-util i { display: block; height: 100%; border-radius: inherit; background: var(--healthy); }
.chart-body, .bars-wrap { flex: 1; min-width: 0; min-height: 0; position: relative; overflow: hidden; }
.chart-body { padding: clamp(7px, .8vh, 12px) clamp(7px, .65vw, 12px) clamp(23px, 3vh, 32px) clamp(37px, 3.1vw, 55px); }
.chart-body svg { display: block; width: 100%; height: 100%; overflow: hidden; }
.grid-line { stroke: var(--border); stroke-width: 1; opacity: .72; vector-effect: non-scaling-stroke; }
.traffic-in-area { fill: url(#trafficInGradient); }
.traffic-out-area { fill: url(#trafficOutGradient); }
.traffic-in-line { fill: none; stroke: var(--traffic-in); stroke-width: 1.8; vector-effect: non-scaling-stroke; }
.traffic-out-line { fill: none; stroke: var(--traffic-out); stroke-width: 1.8; vector-effect: non-scaling-stroke; }
.axis-y { position: absolute; left: clamp(4px, .35vw, 7px); color: #aebdcb; font-size: clamp(6.5px, .45vw, 8.5px); }
.axis-y.y1 { top: 8px; } .axis-y.y2 { top: 34%; } .axis-y.y3 { top: 61%; } .axis-y.y4 { bottom: 25px; }
.axis-x { position: absolute; left: clamp(37px, 3.1vw, 55px); right: clamp(7px, .65vw, 12px); bottom: clamp(14px, 1.75vh, 19px); display: flex; justify-content: space-between; color: #9fb0c1; font-size: clamp(6.2px, .43vw, 8px); }
.chart-legend { position: absolute; left: 50%; bottom: 4px; transform: translateX(-50%); display: flex; gap: 14px; color: #d4dee8; font-size: clamp(6.5px, .45vw, 8.3px); font-weight: 800; }
.legend-line { display: inline-block; width: 12px; height: 3px; margin-right: 4px; vertical-align: middle; }
.bars-wrap { padding: clamp(9px, 1vh, 14px) clamp(7px, .65vw, 12px) clamp(26px, 3.2vh, 34px) clamp(36px, 3vw, 53px); }
.bar-grid { position: absolute; top: clamp(9px, 1vh, 14px); left: clamp(36px, 3vw, 53px); right: clamp(7px, .65vw, 12px); bottom: clamp(26px, 3.2vh, 34px); border-left: 1px solid var(--border-muted); border-bottom: 1px solid var(--border-muted); background: repeating-linear-gradient(to top, transparent 0 33%, rgba(20,49,74,.62) calc(33% + 1px)); }
.bars { position: relative; z-index: 1; width: 100%; height: 100%; display: flex; align-items: flex-end; justify-content: space-around; gap: clamp(2px, .32vw, 6px); }
.bar-item { flex: 1 1 0; min-width: 0; height: 100%; display: flex; flex-direction: column; justify-content: flex-end; align-items: center; }
.bar { width: min(70%, 26px); min-height: 2px; border-radius: 4px 4px 0 0; }
.bar-label { margin-top: 4px; color: #bac8d5; font-size: clamp(6px, .42vw, 8px); font-weight: 800; }
.bars-legend { position: absolute; left: 0; right: 0; bottom: 4px; text-align: center; color: #d4dee8; font-size: clamp(6px, .42vw, 8px); font-weight: 750; white-space: nowrap; }
.bars-legend span { margin: 0 clamp(3px, .35vw, 7px); }
.legend-square { display: inline-block; width: 8px; height: 8px; margin-right: 3px; border-radius: 2px; vertical-align: middle; }

/* Detail row */
.details-row { display: grid; grid-template-columns: minmax(0, 72fr) minmax(0, 28fr); gap: var(--gap); min-width: 0; min-height: 0; }
.table-panel, .properties-panel { min-width: 0; min-height: 0; }
.table-wrap { flex: 1; min-width: 0; min-height: 0; overflow: hidden; padding: 0 clamp(4px, .45vw, 8px) clamp(3px, .35vh, 6px); }
table { width: 100%; height: 100%; table-layout: fixed; border-collapse: collapse; font-size: clamp(7px, .53vw, 10px); }
thead { height: clamp(18px, 2.2vh, 25px); }
tbody { height: calc(100% - clamp(18px, 2.2vh, 25px)); }
thead tr { height: 100%; }
tbody tr { height: 7.69%; }
th, td { min-width: 0; max-width: 0; padding: 1px clamp(2px, .25vw, 5px); border-bottom: 1px solid var(--border-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; vertical-align: middle; }
