   - Cresce nativamente com a área do painel.
   - Fontes, valores, eixos e tabela maiores.
   - Mantém todas as 13 interfaces dentro da tela.
   ===================================================================== */

:host {
  container-type: size !important;
  --gap: clamp(5px, 0.44vw, 9px) !important;
  --pad: clamp(5px, 0.44vw, 9px) !important;
}

#dashboard-root {
  padding: var(--pad) !important;
  gap: var(--gap) !important;
  grid-template-rows:
    minmax(58px, 8fr)
    minmax(98px, 11fr)
    minmax(150px, 19fr)
    minmax(205px, 27fr)
    minmax(250px, 33fr)
    minmax(14px, 2fr) !important;
}

/* Cabeçalho */
.header {
  grid-template-columns: minmax(330px, 1fr) clamp(150px, 13vw, 230px) minmax(470px, 1fr) !important;
  padding: clamp(6px, .62vh, 11px) clamp(12px, .82vw, 18px) !important;
  gap: clamp(10px, .72vw, 16px) !important;
}
.header-title {
  font-size: clamp(21px, 1.42vw, 29px) !important;
  line-height: 1.04 !important;
}
.header-sub {
  margin-top: 4px !important;
  font-size: clamp(9px, .66vw, 12px) !important;
}
.status-chip {
  padding: 3px 9px !important;
  font-size: clamp(8px, .52vw, 10px) !important;
}
.demo-logo {
  height: clamp(40px, 5.2vh, 58px) !important;
}
.header-stat {
  min-width: clamp(72px, 5.8vw, 112px) !important;
}
.header-stat-label {
  font-size: clamp(7.5px, .5vw, 9.5px) !important;
}
.header-stat-value {
  font-size: clamp(10px, .7vw, 14px) !important;
}
.refresh-box {
  height: clamp(30px, 3.7vh, 38px) !important;
  font-size: clamp(8px, .54vw, 10px) !important;
}
.overall-box {
  min-width: clamp(105px, 7.8vw, 145px) !important;
}
.overall-box span {
  font-size: clamp(7px, .46vw, 9px) !important;
}
.overall-box strong {
  font-size: clamp(11px, .78vw, 15px) !important;
}

/* Cards: valor grande, mas sem aumentar a altura geral. */
.cards {
  gap: var(--gap) !important;
}
.kpi {
  padding: clamp(7px, .72vh, 12px) clamp(9px, .68vw, 14px) !important;
  column-gap: clamp(7px, .55vw, 11px) !important;
}
.kpi-icon {
  width: clamp(29px, 2vw, 39px) !important;
  height: clamp(29px, 2vw, 39px) !important;
  font-size: clamp(14px, .98vw, 20px) !important;
}
.kpi-label {
  font-size: clamp(9px, .62vw, 12px) !important;
  letter-spacing: .01em !important;
}
.kpi-value {
  font-size: clamp(25px, 1.72vw, 35px) !important;
  letter-spacing: -.035em !important;
}
.kpi-sub {
  font-size: clamp(8px, .54vw, 10.5px) !important;
}
.sparkline {
  height: clamp(17px, 2.25vh, 25px) !important;
}
.kpi-progress {
  height: clamp(4px, .55vh, 7px) !important;
}

/* Títulos e legendas dos painéis. */
.device-caption,
.panel-header {
  flex-basis: clamp(29px, 3.25vh, 37px) !important;
  height: clamp(29px, 3.25vh, 37px) !important;
  padding-inline: clamp(10px, .72vw, 15px) !important;
}
.panel-title,
.device-caption strong {
  font-size: clamp(10px, .69vw, 13px) !important;
}
.panel-meta,
.device-caption span {
  font-size: clamp(8px, .52vw, 10px) !important;
}

/* Appliance proporcional: mais baixo que antes, mas com textos maiores. */
.chassis {
  width: calc(100% - clamp(24px, 2.2vw, 46px)) !important;
  max-width: none !important;
  margin: clamp(4px, .42vh, 7px) auto !important;
  padding: clamp(7px, .7vh, 11px) clamp(10px, .72vw, 16px) !important;
  grid-template-columns: minmax(155px, 13%) minmax(0, 1fr) minmax(112px, 9%) !important;
}
.pa-logo-img {
  width: clamp(82px, 6vw, 112px) !important;
  height: clamp(29px, 3.7vh, 42px) !important;
}
.sys-leds,
.device-led-panel {
  font-size: clamp(7px, .46vw, 9px) !important;
}
.service-label,
.port-name {
  font-size: clamp(7px, .47vw, 9px) !important;
}
.metal-port {
  width: clamp(39px, 2.55vw, 49px) !important;
  height: clamp(41px, 4.7vh, 51px) !important;
}
.ports-grid {
  width: min(100%, 980px) !important;
  max-width: 980px !important;
  grid-template-columns: repeat(12, minmax(36px, 1fr)) !important;
  gap: clamp(4px, .3vw, 7px) !important;
}
.eth-frame {
  height: clamp(31px, 4.1vh, 43px) !important;
}
.chassis-right {
  grid-template-columns: minmax(45px, 56px) minmax(66px, 86px) !important;
}
.vent {
  height: clamp(54px, 7.2vh, 78px) !important;
}

/* Uplinks e gráficos */
.uplink-item {
  padding: clamp(6px, .66vh, 11px) clamp(9px, .66vw, 14px) !important;
  gap: clamp(8px, .58vw, 12px) !important;
}
.uplink-icon {
  width: clamp(29px, 2vw, 38px) !important;
  height: clamp(29px, 2vw, 38px) !important;
  font-size: clamp(14px, .95vw, 19px) !important;
}
.uplink-name {
  font-size: clamp(9px, .62vw, 12px) !important;
}
.uplink-alias {
  font-size: clamp(8px, .52vw, 10px) !important;
}
.uplink-rate {
  font-size: clamp(13px, .9vw, 18px) !important;
}
.uplink-stats {
  font-size: clamp(8px, .52vw, 10px) !important;
}
.axis-y,
.axis-x,
.chart-legend,
.bar-label,
.bars-legend {
  font-size: clamp(8px, .52vw, 10px) !important;
}
.traffic-in-line,
.traffic-out-line {
  stroke-width: 2 !important;
}
.bar {
  width: min(72%, 30px) !important;
}

/* Tabela e inventário: fonte maior mantendo as 13 linhas. */
table {
  font-size: clamp(8.5px, .58vw, 11px) !important;
}
th {
  font-size: clamp(7.5px, .52vw, 10px) !important;
  padding-inline: clamp(3px, .28vw, 6px) !important;
}
td {
  font-size: clamp(8px, .56vw, 10.8px) !important;
  padding-inline: clamp(3px, .28vw, 6px) !important;
}
.table-status {
  min-width: clamp(39px, 3.4vw, 57px) !important;
  font-size: clamp(7px, .46vw, 9px) !important;
  padding: 2px 6px !important;
}
.util-bar {
  width: clamp(36px, 4.3vw, 72px) !important;
  height: clamp(4px, .5vh, 6px) !important;
}
.prop-label,
.prop-value {
  font-size: clamp(8.5px, .58vw, 11px) !important;
}
.footer {
  font-size: clamp(7px, .49vw, 9px) !important;
}

/* Menu lateral aberto / viewport menor: reduz somente o indispensável. */
@media (max-width: 1450px), (max-height: 760px) {
  #dashboard-root {
    grid-template-rows:
      minmax(52px, 8fr)
      minmax(88px, 11fr)
      minmax(138px, 18fr)
      minmax(182px, 27fr)
      minmax(228px, 34fr)
      minmax(12px, 2fr) !important;
  }
  .header {
    grid-template-columns: minmax(285px, 1fr) 125px minmax(400px, 1fr) !important;
  }
  .header-title { font-size: clamp(18px, 1.34vw, 23px) !important; }
  .kpi-value { font-size: clamp(21px, 1.6vw, 29px) !important; }
  .kpi-label { font-size: clamp(8px, .59vw, 10px) !important; }
  .ports-grid {
    width: 100% !important;
    grid-template-columns: repeat(12, minmax(29px, 1fr)) !important;
    gap: 3px !important;
  }
  .eth-frame { height: clamp(28px, 3.7vh, 38px) !important; }
  table { font-size: clamp(7.5px, .56vw, 9.5px) !important; }
  th { font-size: clamp(6.8px, .48vw, 8.5px) !important; }
  td { font-size: clamp(7.2px, .52vw, 9.2px) !important; }
}


/* ========================================================================
   V8 — APPLIANCE REALISTA E BANCO DE PORTAS COMPACTO
   O HTML mantém a estrutura estável. O CSS desenha o hardware. O onRender
   altera somente estados, títulos e dados retornados pelo Zabbix.
   ======================================================================== */

.appliance-panel {
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.pa800-chassis-realistic {
  grid-template-columns: clamp(155px, 11.5vw, 205px) minmax(520px, 1fr) clamp(130px, 10vw, 185px) !important;
  gap: clamp(10px, .8vw, 18px) !important;
  margin: clamp(4px, .45vh, 7px) !important;
  padding: clamp(8px, .75vh, 13px) clamp(12px, .85vw, 18px) !important;
  background:
    linear-gradient(180deg, rgba(255,255,255,.46) 0 2px, transparent 2px),
    repeating-linear-gradient(90deg, rgba(255,255,255,.035) 0 1px, rgba(0,0,0,.035) 1px 3px),
    linear-gradient(180deg,#d7dcdf 0%,#a8b0b5 8%,#606a71 24%,#394248 45%,#232a2f 69%,#151a1e 100%) !important;
  border-color: #9ca6ac !important;
  box-shadow: inset 0 3px 8px rgba(255,255,255,.24), inset 0 -10px 18px rgba(0,0,0,.4), 0 7px 20px rgba(0,0,0,.42) !important;
}

.pa800-chassis-realistic::after {
  content: "";
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(8,15,20,.52);
  border-radius: 4px;
  pointer-events: none;
}

.appliance-brand-zone,
.appliance-io-zone,
.appliance-right-zone {
  position: relative;
  z-index: 2;
  min-width: 0;
  min-height: 0;
}

.appliance-brand-zone {
  height: 100%;
  display: grid;
  grid-template-rows: auto auto 1fr;
  align-content: center;
  gap: clamp(5px, .6vh, 9px);
  padding-inline: 2px;
}

.appliance-brand-zone .pa-logo-img {
  width: clamp(78px, 6.6vw, 116px) !important;
  height: auto !important;
  object-fit: contain;
  filter: drop-shadow(0 1px 1px rgba(0,0,0,.55));
}

.appliance-sys-leds {
  display: grid !important;
  grid-template-columns: repeat(2, max-content);
  gap: 4px 12px !important;
  color: #f4f7fb !important;
  font-size: clamp(7px, .5vw, 9px) !important;
}

.appliance-sys-leds div {
  display: grid;
  grid-template-columns: 25px 8px;
  align-items: center;
  gap: 5px;
}

.appliance-sys-leds .sys-led.off {
  background: #4d5962 !important;
  box-shadow: none !important;
}

.appliance-legend {
  align-self: end;
  display: grid;
  gap: 3px;
  color: #e5ebf0;
  font-size: clamp(6.7px, .46vw, 8.5px);
}

.appliance-legend span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.legend-dot {
  width: 7px;
  height: 7px;
  border-radius: 2px;
  background: #637281;
}
.legend-dot.up { background: var(--healthy); box-shadow: 0 0 6px rgba(22,214,160,.65); }
.legend-dot.down { background: var(--critical); box-shadow: 0 0 6px rgba(255,64,91,.55); }
.legend-dot.disabled { background: var(--warning); box-shadow: 0 0 6px rgba(255,176,0,.5); }
.legend-dot.unknown { background: #687786; }

.appliance-io-zone {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(12px, .9vw, 18px);
  height: 100%;
}

.service-ports-compact {
  flex: 0 0 auto;
  display: grid !important;
  grid-template-columns: repeat(2, minmax(46px, 54px));
  gap: 8px !important;
  align-items: center;
  padding-right: clamp(10px, .7vw, 14px);
  border-right: 1px solid rgba(8,16,22,.52);
}

.service-ports-compact .service-port {
  gap: 4px !important;
}

.service-ports-compact .metal-port {
  width: clamp(45px, 3.2vw, 54px) !important;
  height: clamp(46px, 5.2vh, 58px) !important;
  padding: 6px !important;
  border-radius: 3px !important;
  background: linear-gradient(180deg,#f0f3f5 0%,#bec6cc 52%,#818b92 100%) !important;
  border: 1px solid rgba(255,255,255,.82) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.75), 0 0 0 1px rgba(24,31,36,.75), 0 2px 5px rgba(0,0,0,.35) !important;
}

.console-port-realistic .service-jack,
.service-ports-compact .service-jack {
  position: relative;
  height: 100% !important;
  background: linear-gradient(180deg,#020405,#06090b) !important;
  border: 3px solid #12181c !important;
  box-shadow: inset 0 0 9px #000 !important;
}

.console-depth {
  position: absolute;
  inset: 7px 6px 4px;
  border: 1px solid #1d252b;
  background: #020304;
}

.service-pins {
  position: absolute;
  top: 3px;
  left: 5px;
  right: 5px;
  height: 7px;
  display: flex;
  justify-content: space-between;
}
.service-pins i { width: 1.5px; height: 7px; background: #d7b92e; box-shadow: 0 0 1px rgba(255,225,87,.5); }

.ethernet-cage {
  flex: 0 1 auto;
  width: min(100%, 525px);
  padding: 8px 10px 10px;
  border: 1px solid rgba(18,28,34,.72);
  border-radius: 4px;
  background: linear-gradient(180deg,rgba(7,12,16,.87),rgba(3,7,10,.9));
  box-shadow: inset 0 1px 10px rgba(0,0,0,.75), 0 0 0 1px rgba(255,255,255,.025);
}

.cage-topline {
  height: 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #d7dfe5;
  font-size: clamp(6px, .42vw, 7.5px);
  letter-spacing: .04em;
  padding: 0 2px;
}

.ports-grid-realistic {
  width: auto !important;
  max-width: none !important;
  display: grid !important;
  grid-template-columns: repeat(6, minmax(50px, 1fr)) !important;
  grid-auto-rows: auto;
  gap: clamp(7px, .55vw, 10px) !important;
  align-items: center;
  justify-content: center;
}

.pa-eth-port {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.pa-eth-port .port-name {
  color: #f2f6f9 !important;
  font-size: clamp(6.4px, .45vw, 8px) !important;
  font-weight: 850;
  line-height: 1;
  text-shadow: 0 1px 1px rgba(0,0,0,.75);
}

.pa-eth-port .eth-frame {
  width: 100% !important;
  height: clamp(38px, 4.6vh, 49px) !important;
  min-width: 0;
  position: relative;
  padding: 6px 5px 5px !important;
  border-radius: 2px !important;
  border: 1px solid rgba(255,255,255,.72) !important;
  background: linear-gradient(180deg,#eef1f2 0%,#c3c9cd 48%,#7b858b 100%) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.86), 0 0 0 1px rgba(20,27,32,.76), 0 2px 5px rgba(0,0,0,.42) !important;
  transition: border-color .2s ease, box-shadow .2s ease;
}

.eth-leds {
  position: absolute;
  top: 3px;
  left: 5px;
  right: 5px;
  display: flex;
  justify-content: space-between;
  pointer-events: none;
}

.eth-led {
  width: 7px;
  height: 5px;
  border-radius: 1px;
  background: #687786;
  box-shadow: none;
}

.pa-eth-port .eth-rj {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: linear-gradient(180deg,#020405,#07100c 63%,#020504 64%) !important;
  border: 3px solid #12181a !important;
  border-radius: 1px !important;
  box-shadow: inset 0 0 9px #000 !important;
}

.eth-pins {
  position: absolute;
  top: 2px;
  left: 5px;
  right: 5px;
  height: 8px;
  display: flex;
  justify-content: space-between;
}
.eth-pins i { width: 1.4px; height: 8px; background: #d6b827; box-shadow: 0 0 1px rgba(255,229,91,.5); }

.eth-latch {
  position: absolute;
  left: 28%;
  right: 28%;
  bottom: 0;
  height: 5px;
  border-radius: 1px 1px 0 0;
  background: #26332c;
  border-top: 1px solid #3e5247;
}

.pa-eth-port[data-status="up"] .eth-frame {
  border-color: var(--healthy) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.86), 0 0 0 2px rgba(22,214,160,.58), 0 0 10px rgba(22,214,160,.32) !important;
}
.pa-eth-port[data-status="up"] .eth-led { background: var(--healthy); box-shadow: 0 0 5px rgba(22,214,160,.78); }
.pa-eth-port[data-status="down"] .eth-frame {
  border-color: var(--critical) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.86), 0 0 0 2px rgba(255,64,91,.64), 0 0 10px rgba(255,64,91,.3) !important;
}
.pa-eth-port[data-status="down"] .eth-led { background: var(--critical); box-shadow: 0 0 5px rgba(255,64,91,.74); }
.pa-eth-port[data-status="disabled"] .eth-frame {
  border-color: var(--warning) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.86), 0 0 0 2px rgba(255,176,0,.58), 0 0 10px rgba(255,176,0,.25) !important;
}
.pa-eth-port[data-status="disabled"] .eth-led { background: var(--warning); box-shadow: 0 0 5px rgba(255,176,0,.72); }
.pa-eth-port[data-status="unknown"] .eth-frame { filter: saturate(.25) brightness(.84); }

.appliance-right-zone {
  height: 100%;
  display: grid;
  grid-template-columns: minmax(45px, .65fr) minmax(75px, 1fr);
  gap: clamp(7px, .6vw, 12px);
  align-items: center;
}

.appliance-led-panel {
  color: #f4f7fb !important;
  font-size: clamp(6.5px, .46vw, 8.5px) !important;
}

.vent-realistic {
  height: clamp(72px, 10.5vh, 105px) !important;
  background-color: #050708 !important;
  background-image:
    radial-gradient(circle at center, #303940 0 31%, transparent 34%),
    linear-gradient(180deg,rgba(255,255,255,.02),rgba(0,0,0,.08)) !important;
  background-size: 11px 10px, 100% 100% !important;
  border: 1px solid #58636b !important;
  box-shadow: inset 0 0 16px #000, 0 0 0 1px rgba(255,255,255,.035) !important;
}

@media (max-width: 1450px), (max-height: 760px) {
  .pa800-chassis-realistic {
    grid-template-columns: 128px minmax(470px, 1fr) 105px !important;
    gap: 7px !important;
    padding: 6px 9px !important;
  }
  .appliance-legend { display: none; }
  .appliance-brand-zone .pa-logo-img { width: 75px !important; }
  .service-ports-compact { grid-template-columns: repeat(2, 44px); gap: 5px !important; padding-right: 7px; }
  .service-ports-compact .metal-port { width: 44px !important; height: 45px !important; }
  .ethernet-cage { width: min(100%, 465px); padding: 6px 7px 7px; }
  .ports-grid-realistic { grid-template-columns: repeat(6, minmax(43px, 1fr)) !important; gap: 5px !important; }
  .pa-eth-port .eth-frame { height: 35px !important; padding: 5px 4px 4px !important; }
  .appliance-right-zone { grid-template-columns: 1fr; }
  .appliance-led-panel { display: none; }
}


/* ========================================================================
   V9 — PA-800 COMPACTO / REALISTA + TABELA E INVENTÁRIO MAIS LEGÍVEIS
   Sem scale, zoom ou dimensões fixas do dashboard. O appliance é compacto,
   inspirado no chassi real da família PA-800, e as 12 portas permanecem
   dinâmicas via IDs estáveis e onRender.
   ======================================================================== */

#dashboard-root {
  grid-template-rows:
    minmax(56px, 7.2fr)
    minmax(92px, 11.5fr)
    minmax(125px, 15.5fr)
    minmax(190px, 25fr)
    minmax(285px, 39fr)
    minmax(12px, 1.8fr) !important;
}

.compact-pa800-panel {
  overflow: hidden !important;
}

.compact-pa800-panel .device-caption {
  height: clamp(27px, 3.1vh, 34px) !important;
  flex-basis: clamp(27px, 3.1vh, 34px) !important;
}

.pa800-compact-shell {
  width: min(76%, 1120px);
  height: calc(100% - clamp(34px, 4.2vh, 43px));
  min-height: 82px;
  max-height: 126px;
  margin: clamp(4px, .45vh, 7px) auto;
  display: grid;
  grid-template-columns: clamp(42px, 4.2vw, 72px) minmax(0, 1fr) clamp(42px, 4.2vw, 72px);
  align-items: stretch;
  border: 1px solid #2cb6d0;
  border-radius: 4px;
  background: linear-gradient(180deg, #5cc9e3 0%, #1689aa 7%, #0a435b 20%, #092c3d 78%, #061922 100%);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.58),
    inset 0 -5px 12px rgba(0,0,0,.62),
    0 6px 16px rgba(0,0,0,.42);
  overflow: hidden;
  position: relative;
}

.pa800-compact-shell::before {
  content: "";
  position: absolute;
  inset: 3px;
  border: 1px solid rgba(160,238,255,.22);
  border-radius: 2px;
  pointer-events: none;
}

.pa800-side-vent {
  min-width: 0;
  background-color: #082838;
  background-image:
    radial-gradient(circle, rgba(31,200,233,.75) 0 1.2px, transparent 1.4px),
    linear-gradient(180deg, rgba(255,255,255,.08), transparent 28%, rgba(0,0,0,.22));
  background-size: 8px 8px, 100% 100%;
  border-color: rgba(35,196,224,.45);
  border-style: solid;
  box-shadow: inset 0 0 9px rgba(0,0,0,.72);
}
.pa800-side-vent-left { border-width: 0 1px 0 0; }
.pa800-side-vent-right { border-width: 0 0 0 1px; }

.pa800-face {
  min-width: 0;
  min-height: 0;
  display: grid;
