#dashboard-root {
  grid-template-rows:
    minmax(62px, 7.5fr)
    minmax(96px, 12.5fr)
    minmax(98px, 12.5fr)
    minmax(184px, 24.5fr)
    minmax(278px, 41fr)
    minmax(13px, 2fr) !important;
}

.header {
  grid-template-columns: minmax(330px, 1fr) clamp(175px, 15vw, 265px) minmax(465px, 1fr) !important;
  padding-inline: clamp(12px, 1vw, 21px) !important;
}
.header-title {
  font-size: clamp(20px, 1.48vw, 25px) !important;
  line-height: 1.02 !important;
}
.header-sub {
  margin-top: clamp(3px, .34vh, 6px) !important;
  font-size: clamp(9px, .68vw, 12.5px) !important;
  gap: clamp(5px, .42vw, 9px) !important;
}
.status-chip {
  padding: 3px 10px !important;
  font-size: clamp(8px, .54vw, 10px) !important;
}
.status-chip::before { width: 7px !important; height: 7px !important; }
.header-center { overflow: visible !important; }
.demo-logo {
  width: min(100%, clamp(175px, 14.2vw, 255px)) !important;
  height: clamp(46px, 6.4vh, 72px) !important;
  max-height: 100% !important;
  object-fit: contain !important;
  object-position: center !important;
  image-rendering: auto !important;
  filter: drop-shadow(0 2px 3px rgba(0,0,0,.75)) !important;
}
.header-stat { min-width: clamp(74px, 6vw, 112px) !important; }
.header-stat-label { font-size: clamp(7.5px, .51vw, 9.5px) !important; }
.header-stat-value { font-size: clamp(9.5px, .72vw, 13.5px) !important; }
.refresh-box {
  height: clamp(30px, 3.8vh, 38px) !important;
  font-size: clamp(8px, .56vw, 10.5px) !important;
}
.overall-box { min-width: clamp(105px, 8vw, 145px) !important; }
.overall-box span { font-size: clamp(7px, .49vw, 9px) !important; }
.overall-box strong { font-size: clamp(10.5px, .8vw, 15px) !important; }

.cards { gap: clamp(6px, .6vw, 11px) !important; }
.kpi { padding: clamp(8px, .84vh, 13px) clamp(9px, .72vw, 14px) !important; }
.kpi-top { gap: clamp(7px, .55vw, 11px) !important; }
.kpi-icon {
  width: clamp(32px, 2.45vw, 45px) !important;
  height: clamp(32px, 2.45vw, 45px) !important;
  border-radius: clamp(8px, .65vw, 12px) !important;
}
.kpi-icon svg { width: 66% !important; height: 66% !important; stroke-width: 2.15 !important; }
.kpi-label { font-size: clamp(8.7px, .66vw, 12px) !important; }
.kpi-value {
  margin-left: clamp(38px, 3vw, 54px) !important;
  font-size: clamp(23px, 1.78vw, 28px) !important;
}
.kpi-sub { font-size: clamp(7.6px, .54vw, 10.2px) !important; }
.sparkline { height: clamp(20px, 3.1vh, 33px) !important; }
.kpi-progress { height: clamp(5px, .62vh, 8px) !important; }

.panel-header,
.device-caption {
  height: clamp(30px, 3.6vh, 40px) !important;
  flex-basis: clamp(30px, 3.6vh, 40px) !important;
  padding-inline: clamp(10px, .75vw, 15px) !important;
}
.panel-title,
.device-caption strong { font-size: clamp(10px, .72vw, 13.5px) !important; }
.panel-meta,
.device-caption span { font-size: clamp(8px, .54vw, 10.5px) !important; }

/* O appliance permanece compacto; apenas suas legendas ganham nitidez. */
.pa800-compact-shell { max-height: 112px !important; }
.compact-ports-grid .port-name { font-size: clamp(6px, .42vw, 8px) !important; }
.compact-ports-grid .port-alias-short {
  height: clamp(7px, .7vh, 11px) !important;
  font-size: clamp(5.3px, .38vw, 7.3px) !important;
}
.compact-service-port .service-label { font-size: clamp(6px, .43vw, 8px) !important; }
.pa800-status-mini,
.pa800-led-cluster { font-size: clamp(6px, .43vw, 8px) !important; }

.uplinks-content { padding: clamp(5px, .55vh, 9px) clamp(8px, .65vw, 13px) !important; }
.uplink { grid-template-columns: clamp(30px, 2.5vw, 42px) minmax(0,1fr) clamp(84px, 7.4vw, 124px) !important; }
.uplink-icon { width: clamp(29px, 2.35vw, 40px) !important; height: clamp(29px, 2.35vw, 40px) !important; }
.uplink-name { font-size: clamp(8.7px, .64vw, 11.5px) !important; }
.uplink-alias { font-size: clamp(7.8px, .56vw, 10.5px) !important; }
.uplink-rate { font-size: clamp(12px, .95vw, 17.5px) !important; }
.uplink-stats { font-size: clamp(7.5px, .52vw, 9.8px) !important; }

.axis-y,
.axis-x { font-size: clamp(8.8px, .58vw, 11px) !important; }
.chart-legend,
.bars-legend { font-size: clamp(8.7px, .58vw, 11px) !important; }
.bar-label { font-size: clamp(7.5px, .52vw, 10px) !important; }

/* Lista e inventário: mais legíveis sem perder as 13 interfaces. */
.table-panel .panel-title,
.properties-panel .panel-title { font-size: clamp(12.5px, .82vw, 15.8px) !important; }
.table-panel .panel-meta,
.properties-panel .panel-meta { font-size: clamp(9.3px, .62vw, 11.5px) !important; }
table { font-size: clamp(10.8px, .71vw, 13.7px) !important; }
th {
  font-size: clamp(9.6px, .63vw, 12px) !important;
  line-height: 1.05 !important;
}
td {
  font-size: clamp(10.2px, .68vw, 13px) !important;
  line-height: 1.05 !important;
}
.table-status {
  min-width: clamp(49px, 3.75vw, 67px) !important;
  font-size: clamp(8.4px, .56vw, 10.5px) !important;
}
.alias-cell { font-size: inherit !important; }
.prop-label,
.prop-value { font-size: clamp(11px, .73vw, 14px) !important; }
.footer { font-size: clamp(7.5px, .52vw, 10px) !important; }

@media (max-width: 1450px), (max-height: 780px) {
  #dashboard-root {
    grid-template-rows:
      minmax(55px, 7.2fr)
      minmax(88px, 11.8fr)
      minmax(88px, 11.8fr)
      minmax(168px, 24fr)
      minmax(255px, 43.2fr)
      minmax(11px, 2fr) !important;
  }
  .header { grid-template-columns: minmax(285px,1fr) clamp(145px,13vw,205px) minmax(420px,1fr) !important; }
  .demo-logo { width: min(100%, 205px) !important; height: clamp(40px, 5.8vh, 58px) !important; }
  .header-title { font-size: clamp(18px, 1.4vw, 25px) !important; }
  .kpi-icon { width: clamp(29px, 2.3vw, 38px) !important; height: clamp(29px, 2.3vw, 38px) !important; }
  .kpi-value { font-size: clamp(21px, 1.62vw, 30px) !important; margin-left: 34px !important; }
  .kpi-label { font-size: clamp(8px, .62vw, 10.5px) !important; }
  table { font-size: clamp(9.8px, .68vw, 12px) !important; }
  th { font-size: clamp(8.8px, .6vw, 10.5px) !important; }
  td { font-size: clamp(9.3px, .65vw, 11.5px) !important; }
  .prop-label,
  .prop-value { font-size: clamp(10px, .68vw, 12px) !important; }
}


/* =====================================================================
   V20 — NOMES COMPLETOS DOS CARDS
   Mantém valores, ícones e dados; remove somente o corte por reticências.
   ===================================================================== */
.cards .kpi {
  grid-template-columns: minmax(0, 1fr) auto !important;
  column-gap: clamp(5px, .42vw, 9px) !important;
}

.cards .kpi-top {
  min-width: 0 !important;
  overflow: visible !important;
  align-items: center !important;
}

.cards .kpi-label {
  display: block !important;
  min-width: 0 !important;
  max-width: none !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
  line-height: 1.05 !important;
  word-break: normal !important;
  overflow-wrap: normal !important;
  font-size: clamp(8px, .58vw, 11px) !important;
}

/* Permite até duas linhas sem aumentar a altura dos cards. */
.cards .kpi-top {
  line-height: 1.05 !important;
}

.cards .kpi-value {
  margin-left: 0 !important;
  flex-shrink: 0 !important;
  font-size: clamp(21px, 1.62vw, 30px) !important;
}

@media (max-width: 1450px), (max-height: 780px) {
  .cards .kpi-label {
    font-size: clamp(7.4px, .54vw, 9.8px) !important;
  }
  .cards .kpi-value {
    font-size: clamp(19px, 1.48vw, 27px) !important;
  }
}


