/* Command Center V3: leitura executiva e prioridade operacional */
.health-score-box {
  display:flex; align-items:center; gap:7px; height:clamp(34px,4.2vh,48px);
  padding:4px 9px 4px 5px; border:1px solid rgba(38,140,255,.34);
  border-radius:10px; background:linear-gradient(135deg,rgba(38,140,255,.12),rgba(22,214,160,.06));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.04),0 0 18px rgba(38,140,255,.06);
}
.health-score-ring {
  --score-angle:0deg; --score-color:var(--unknown); width:clamp(28px,2.3vw,38px); aspect-ratio:1;
  display:grid; place-items:center; flex:0 0 auto; border-radius:50%;
  background:radial-gradient(circle at center,#04101a 55%,transparent 57%),conic-gradient(var(--score-color) var(--score-angle),rgba(101,120,139,.2) 0);
  filter:drop-shadow(0 0 5px color-mix(in srgb,var(--score-color) 40%,transparent));
}
.health-score-ring strong { font-size:clamp(9px,.72vw,13px); color:#fff; line-height:1; }
.health-score-copy { display:grid; line-height:1.05; min-width:72px; }
.health-score-copy small { color:var(--text-3); font-size:clamp(5.5px,.38vw,7.5px); font-weight:850; letter-spacing:.09em; }
.health-score-copy b { margin-top:3px; color:var(--healthy-bright); font-size:clamp(7px,.5vw,9px); letter-spacing:.04em; }
.health-score-box.warning { border-color:rgba(255,176,0,.5); background:linear-gradient(135deg,rgba(255,176,0,.14),rgba(255,176,0,.03)); }
.health-score-box.warning .health-score-copy b { color:var(--warning-bright); }
.health-score-box.critical { border-color:rgba(255,64,91,.62); background:linear-gradient(135deg,rgba(255,64,91,.17),rgba(255,64,91,.04)); animation:nocPulse 2.2s ease-in-out infinite; }
.health-score-box.critical .health-score-copy b { color:var(--critical-bright); }
@keyframes nocPulse { 50% { box-shadow:0 0 20px rgba(255,64,91,.2),inset 0 1px 0 rgba(255,255,255,.04); } }
@media (max-width:1300px){ .health-score-copy{display:none}.health-score-box{padding-right:5px}.health-score-ring{width:30px} }


/* V4 Animated Appliance — movimento orientado aos estados reais do Zabbix */
.pa800-compact-shell { overflow:hidden !important; isolation:isolate; }
.pa800-compact-shell::after {
  content:""; position:absolute; inset:0; z-index:8; pointer-events:none;
  background:linear-gradient(105deg,transparent 0 42%,rgba(38,140,255,.025) 47%,rgba(22,214,160,.10) 50%,rgba(38,140,255,.025) 53%,transparent 58% 100%);
  transform:translateX(-115%); animation:fortigateScan 9s ease-in-out infinite;
}
@keyframes fortigateScan { 0%,68%{transform:translateX(-115%)} 88%,100%{transform:translateX(115%)} }

.pa800-status-mini .right-led,
.pa800-led-cluster .right-led {
  animation:systemHeartbeat 2.6s ease-in-out infinite;
}
.pa800-status-mini span:nth-child(2) .right-led,
.pa800-led-cluster span:nth-child(2) .right-led { animation-delay:.45s; }
.pa800-status-mini .warn,
.pa800-led-cluster .warn { animation:systemWarn 3.4s ease-in-out infinite; }
@keyframes systemHeartbeat { 0%,100%{opacity:.62;box-shadow:0 0 3px currentColor} 48%{opacity:1;box-shadow:0 0 9px currentColor,0 0 15px currentColor} }
@keyframes systemWarn { 0%,82%,100%{opacity:.62} 88%,94%{opacity:1;box-shadow:0 0 10px #ffb000} }

.pa-eth-port { transition:transform .2s ease,filter .2s ease; transform-origin:center; }
.pa-eth-port:hover { transform:translateY(-2px) scale(1.12); z-index:20; filter:brightness(1.28); }
.pa-eth-port:hover .port-name { color:#fff !important; text-shadow:0 0 7px #268cff; }
.pa-eth-port .eth-frame { transition:border-color .3s ease,box-shadow .3s ease,filter .3s ease; }

.pa-eth-port[data-status="up"] .eth-led-left {
  animation:rxPulse 1.35s steps(2,end) infinite; animation-delay:var(--port-delay,0s);
}
.pa-eth-port[data-status="up"] .eth-led-right {
  animation:txPulse 1.8s steps(2,end) infinite; animation-delay:calc(var(--port-delay,0s) + .22s);
}
.pa-eth-port.is-traffic[data-status="up"] .eth-frame {
  animation:activePortGlow 2.2s ease-in-out infinite; animation-delay:var(--port-delay,0s);
}
.pa-eth-port.is-busy[data-status="up"] .eth-frame { animation-duration:1.05s; }
.pa-eth-port.is-busy[data-status="up"] .eth-led-left,
.pa-eth-port.is-busy[data-status="up"] .eth-led-right { animation-duration:.58s; }
@keyframes rxPulse { 0%,52%{opacity:.32;box-shadow:none} 53%,100%{opacity:1;box-shadow:0 0 7px #16d6a0,0 0 12px rgba(22,214,160,.55)} }
@keyframes txPulse { 0%,58%{opacity:.28;box-shadow:none} 59%,100%{opacity:1;box-shadow:0 0 7px #ffcf33,0 0 11px rgba(255,207,51,.48)} }
@keyframes activePortGlow { 0%,100%{box-shadow:inset 0 0 3px rgba(22,214,160,.1),0 0 2px rgba(22,214,160,.12)} 50%{box-shadow:inset 0 0 7px rgba(22,214,160,.28),0 0 8px rgba(22,214,160,.34)} }

.pa-eth-port[data-status="down"] .eth-frame { animation:downPortAlert 2.8s ease-in-out infinite; }
@keyframes downPortAlert { 0%,75%,100%{box-shadow:0 0 2px rgba(255,64,91,.18)} 86%{box-shadow:0 0 9px rgba(255,64,91,.72);filter:brightness(1.28)} }

@media (prefers-reduced-motion:reduce) {
  .pa800-compact-shell::after,.right-led,.eth-led,.eth-frame { animation:none !important; }
  .pa-eth-port:hover { transform:none; }
}


/* V5 — chassi ampliado, duas fileiras completas e animação de alto contraste */
#dashboard-root {
