/* A luz se propaga pela porta para ficar visível mesmo em telas grandes. */
.pa-eth-port.is-traffic[data-status="up"] .eth-frame::after {
  content:""; position:absolute; inset:-25% -80%; z-index:5; pointer-events:none;
  background:linear-gradient(105deg,transparent 35%,rgba(255,255,255,.08) 43%,rgba(22,214,160,.88) 50%,rgba(255,214,57,.42) 55%,transparent 64%);
  transform:translateX(-45%); animation:dataBurst 1.25s linear infinite;
  animation-delay:var(--port-delay,0s); mix-blend-mode:screen;
}
.pa-eth-port.is-busy[data-status="up"] .eth-frame::after { animation-duration:.48s; }
@keyframes dataBurst { from{transform:translateX(-48%)} to{transform:translateX(48%)} }

.pa-eth-port[data-status="up"] .eth-led-left,
.pa-eth-port[data-status="up"] .eth-led-right {
  width:5px !important; height:5px !important; opacity:1;
}
.pa-eth-port[data-status="up"] .eth-led-left { animation-duration:.7s !important; box-shadow:0 0 7px #16d6a0; }
.pa-eth-port[data-status="up"] .eth-led-right { animation-duration:.95s !important; box-shadow:0 0 7px #ffd33d; }
.pa-eth-port.is-busy[data-status="up"] .eth-led-left,
.pa-eth-port.is-busy[data-status="up"] .eth-led-right { animation-duration:.32s !important; }
.pa-eth-port.is-traffic[data-status="up"] .eth-frame {
  border-color:rgba(39,255,174,.92) !important;
  animation:strongPortGlow 1.15s ease-in-out infinite !important;
  animation-delay:var(--port-delay,0s) !important;
}
@keyframes strongPortGlow {
  0%,100%{filter:brightness(1);box-shadow:0 0 3px rgba(22,214,160,.45),inset 0 0 5px rgba(22,214,160,.2)}
  50%{filter:brightness(1.35);box-shadow:0 0 13px rgba(22,214,160,.95),0 0 20px rgba(38,140,255,.35),inset 0 0 9px rgba(22,214,160,.46)}
}
.pa-eth-port[data-status="down"] .eth-frame { animation:strongDownAlert 1.65s ease-in-out infinite !important; }
@keyframes strongDownAlert { 0%,100%{border-color:#9c2338;box-shadow:0 0 3px rgba(255,64,91,.3)} 50%{border-color:#ff405b;box-shadow:0 0 12px rgba(255,64,91,.88);filter:brightness(1.35)} }

.pa800-compact-shell::after {
  background:linear-gradient(105deg,transparent 0 38%,rgba(38,140,255,.10) 44%,rgba(22,214,160,.34) 50%,rgba(38,140,255,.12) 56%,transparent 62% 100%) !important;
  animation:fortigateScan 4.2s linear infinite !important;
}
.pa800-status-mini .right-led,.pa800-led-cluster .right-led { animation-duration:1.25s !important; filter:brightness(1.5); }

@media (max-width:1450px),(max-height:780px) {
  #dashboard-root { grid-template-rows:minmax(44px,.58fr) minmax(72px,.94fr) minmax(144px,2fr) minmax(132px,1.82fr) minmax(170px,2.8fr) minmax(10px,.13fr) !important; }
  .pa800-compact-shell { width:min(96%,1280px) !important; min-height:106px !important; }
