/* ========================================================================
   V6.5.19 — SEMÂNTICA NOC DAS PORTAS
   UP = verde | DOWN = cinza | CRÍTICO = vermelho
   DISABLED = amarelo | N/D = cinza claro
   ======================================================================== */

/* Legenda compacta no caption */
.port-status-legend{
  display:flex !important;
  align-items:center !important;
  justify-content:flex-end !important;
  gap:clamp(7px,.55vw,12px) !important;
  color:#a8bacb !important;
  font-size:clamp(6.5px,.46vw,9px) !important;
  overflow:visible !important;
}
.port-status-legend b{
  display:inline-flex;
  align-items:center;
  gap:4px;
  font-weight:800;
  white-space:nowrap;
}
.legend-dot{
  width:7px;
  height:7px;
  border-radius:50%;
  display:inline-block;
  box-shadow:0 0 5px currentColor;
}
.legend-up{background:#20d99a;color:#20d99a}
.legend-down{background:#71808c;color:#71808c}
.legend-critical{background:#ff405b;color:#ff405b}
.legend-disabled{background:#f4c400;color:#f4c400}
.legend-unknown{background:#a7b5c1;color:#a7b5c1}

/* DOWN comum: neutro, sem sensação de incidente */
.pa-eth-port[data-status="down"] .eth-frame,
.eth-frame.down{
  border-color:#71808c !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.90),
    0 0 0 2px rgba(113,128,140,.26) !important;
  filter:saturate(.45) brightness(.90) !important;
}
.pa-eth-port[data-status="down"] .eth-led,
.eth-frame.down::before,
.eth-frame.down::after{
  background:#71808c !important;
  box-shadow:none !important;
}

/* CRÍTICO: vermelho reservado para porta importante que caiu */
.pa-eth-port[data-status="critical"] .eth-frame,
.eth-frame.critical{
  border-color:#ff405b !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.92),
    0 0 0 2px rgba(255,64,91,.72),
    0 0 12px rgba(255,64,91,.38) !important;
  animation:nocPortCriticalPulse 1.8s ease-in-out infinite !important;
}
.pa-eth-port[data-status="critical"] .eth-led,
.eth-frame.critical::before,
.eth-frame.critical::after{
  background:#ff405b !important;
  box-shadow:0 0 6px rgba(255,64,91,.78) !important;
}

/* UP permanece verde */
.pa-eth-port[data-status="up"] .eth-frame,
.eth-frame.up{
  border-color:#20d99a !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.90),
    0 0 0 2px rgba(32,217,154,.54),
    0 0 10px rgba(32,217,154,.26) !important;
}

/* DISABLED reservado para quando esse estado estiver disponível */
.pa-eth-port[data-status="disabled"] .eth-frame,
.eth-frame.disabled{
  border-color:#f4c400 !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.90),
    0 0 0 2px rgba(244,196,0,.54),
    0 0 9px rgba(244,196,0,.23) !important;
}

/* N/D */
.pa-eth-port[data-status="unknown"] .eth-frame,
.eth-frame.unknown{
  border-color:#a7b5c1 !important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.90) !important;
  filter:saturate(.30) brightness(.86) !important;
}

@keyframes nocPortCriticalPulse{
  0%,100%{
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,.92),
      0 0 0 2px rgba(255,64,91,.60),
      0 0 8px rgba(255,64,91,.26);
  }
  50%{
    box-shadow:
      inset 0 1px 0 rgba(255,255,255,.92),
      0 0 0 2px rgba(255,64,91,.88),
      0 0 15px rgba(255,64,91,.46);
  }
}

@media(max-width:1450px),(max-height:780px){
  .port-status-legend{gap:5px !important;font-size:6.2px !important}
  .legend-dot{width:6px;height:6px}
}

/* ========================================================================
   V6.5.20 — SEMÂNTICA VALIDADA COM O ZABBIX
   Fonte de verdade disponível: status operacional.
   UP = up(1)
   DOWN = down(2)
   N/D = sem item/sem retorno
   CRÍTICO = apenas porta física explicitamente cadastrada + DOWN
   Não usamos DISABLED porque não há status administrativo coletado.
   ======================================================================== */

.port-status-legend .legend-disabled{
  display:none !important;
}

/* DOWN operacional comum: neutro/cinza */
.pa-eth-port[data-status="down"] .eth-frame,
.eth-frame.down{
  border-color:#71808c !important;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,.90),
    0 0 0 2px rgba(113,128,140,.24) !important;
  filter:saturate(.40) brightness(.90) !important;
}
.pa-eth-port[data-status="down"] .eth-led,
.eth-frame.down::before,
.eth-frame.down::after{
  background:#71808c !important;
  box-shadow:none !important;
}

/* N/D: não confundir ausência de item com DOWN */
.pa-eth-port[data-status="unknown"] .eth-frame,
.eth-frame.unknown{
  border-color:#a7b5c1 !important;
  box-shadow:
