/* Temperatura confirmada no Zabbix:
   Sensor TMP 1 CPUTIN: valor
   Query C traz todos os "Sensor TMP ... valor" e o parser escolhe CPUTIN.
*/
let temperature=null;
let temperatureFrame=null;

function descriptorMatchesCPUTIN(text){
  return /TMP\s*1\s*CPUTIN.*valor|CPUTIN/i.test(String(text||''));
}

// 1) Registros da própria query C.
for(const r of records){
  if(r.refId && r.refId!=='C') continue;
  if(!descriptorMatchesCPUTIN(r.label)) continue;
  const n=normalizeTemperature(r.value);
  if(Number.isFinite(n)){
    temperature=n;
    temperatureFrame=r.frame || null;
    break;
  }
}

// 2) Frames da query C, usando descriptor completo.
if(!Number.isFinite(temperature)){
  for(const frame of frames){
    const ref=frameRef(frame);
    if(ref && ref!=='C') continue;
    const descriptor=descriptorOf(frame);
    if(!descriptorMatchesCPUTIN(descriptor)) continue;
    const n=normalizeTemperature(latest(frame));
    if(Number.isFinite(n)){
      temperature=n;
      temperatureFrame=frame;
      break;
    }
  }
}

// 3) Fallback SEM depender do refId: alguns retornos do plugin podem perder o refId.
if(!Number.isFinite(temperature)){
  for(const frame of frames){
    const descriptor=descriptorOf(frame);
    if(!descriptorMatchesCPUTIN(descriptor)) continue;
    const n=normalizeTemperature(latest(frame));
    if(Number.isFinite(n)){
      temperature=n;
      temperatureFrame=frame;
      break;
    }
  }
}

// 4) Fallback para qualquer TMP com valor plausível.
//    Prefere CPUTIN, mas permite TMP 2 PECI caso CPUTIN não venha no frame.
if(!Number.isFinite(temperature)){
  const tmpCandidates=[];
  for(const frame of frames){
    const ref=frameRef(frame);
    if(ref && ref!=='C') continue;
    const descriptor=descriptorOf(frame);
    if(!/Sensor\s*TMP|TMP\s*\d|CPUTIN|PECI/i.test(descriptor)) continue;
    const n=normalizeTemperature(latest(frame));
    if(Number.isFinite(n)) tmpCandidates.push({n,frame,descriptor});
  }
  const preferred=tmpCandidates.find(x=>/CPUTIN/i.test(x.descriptor)) || tmpCandidates[0];
  if(preferred){
    temperature=preferred.n;
    temperatureFrame=preferred.frame;
  }
}

