function normalizeHaSync(value){
  const raw=String(value??'').trim();
  if(!raw) return {known:false, synced:false, label:'N/D'};

  if(/not\s+synchron|não\s+sincron/i.test(raw)){
    return {known:true, synced:false, label:'Não sincronizado'};
  }

  if(/synchronized|synchronised|sincronizado/i.test(raw)){
    return {known:true, synced:true, label:'Sincronizado'};
  }

  const n=parseNumeric(raw,null);
  if(Number.isFinite(n)){
    if(n===1) return {known:true, synced:true, label:'Sincronizado'};
    if(n===0) return {known:true, synced:false, label:'Não sincronizado'};
    return {known:true, synced:false, label:`Status ${n}`};
  }

  return {known:true, synced:false, label:raw};
}

