const preferredOrder = name => {
  const p = String(name).match(/^port(\d+)$/i);
  if (p) return Number(p[1]);
  const x = String(name).match(/^x(\d+)$/i);
  if (x) return 100 + Number(x[1]);
  if (/^mgmt$/i.test(name)) return 150;
  if (/^LACP_/i.test(name)) return 200;
  if (/^VLAN_/i.test(name)) return 300;
  if (/^VPN_/i.test(name)) return 400;
  return 500;
};
const interfaceNames = Array.from(allNames).sort((a,b) => preferredOrder(a)-preferredOrder(b) || String(a).localeCompare(String(b)));

function interfaceType(name, raw) {
  const n = String(name || '');
  const txt = String(raw || '').toLowerCase();
  if (/^mgmt$/i.test(n)) return 'Management';
  if (/^port\d+$/i.test(n) || /^x\d+$/i.test(n)) return 'Física';
  if (/^vlan_/i.test(n) || /l2vlan/.test(txt)) return 'VLAN';
  if (/^lacp_/i.test(n)) return 'LACP';
  if (/vpn|spoke|tunnel|túnel|tunnel/.test(n.toLowerCase()) || /tunnel/.test(txt)) return 'Túnel';
  if (/loopback/i.test(n)) return 'Loopback';
  return 'Interface';
}
const interfaces = interfaceNames.map(name => {
  const operRaw = mapValue(operMap,name);
  const oper = parseNumeric(operRaw, null);
  const operTxt = String(operRaw ?? '').toLowerCase();
  let status = (oper === 1 || /\bup\b/.test(operTxt))
    ? (/^mgmt$/i.test(name) ? 'management' : 'up')
    : (oper === 2 || /\bdown\b/.test(operTxt)) ? 'down' : 'unknown';
  const speed = mapNumber(speedMap,name);
  const input = mapNumber(inMap,name);
  const output = mapNumber(outMap,name);
  const inErrors = mapNumber(inErrMap,name);
  const outErrors = mapNumber(outErrMap,name);
  const inDiscards = mapNumber(inDiscMap,name);
  const outDiscards = mapNumber(outDiscMap,name);
  const maxDir = Math.max(Number.isFinite(input)?input:0, Number.isFinite(output)?output:0);
  const util = Number.isFinite(speed) && speed > 0 && maxDir >= 0 ? (maxDir / speed * 100) : null;
  const alias = aliasMap.get(name) || '—';
  return {
    name, short: name.replace(/^VPN_SDWAN/i,'SD').replace(/^VLAN_/i,'V').replace(/^port/i,'P'),
    status, type: interfaceType(name,mapValue(typeMap,name)), alias, speed, input, output,
    errors: Number.isFinite(inErrors)||Number.isFinite(outErrors) ? (inErrors||0)+(outErrors||0) : null,
    discards: Number.isFinite(inDiscards)||Number.isFinite(outDiscards) ? (inDiscards||0)+(outDiscards||0) : null,
    util,
    traffic: Number.isFinite(input)||Number.isFinite(output) ? (input||0)+(output||0) : null
  };
});

