function updatePhysicalPort(item) {
  if (!/^(?:port(?:[1-9]|1\d|2[0-4])|x[1-4])$/i.test(item.name)) return;

  const wrapper=q(`port-${item.name.toLowerCase()}`);
  if(!wrapper) return;

  const physicalName=String(item.name||'').toLowerCase();

  /* Regra validada:
     - Zabbix up(1)   -> UP
     - Zabbix down(2) -> DOWN
     - sem item       -> N/D
     - CRÍTICO somente se a porta física estiver explicitamente cadastrada
       em criticalPhysicalPorts e estiver DOWN.
  */
  const visualStatus =
    item.status === 'down' && criticalPhysicalPorts.has(physicalName)
      ? 'critical'
      : item.status;

  wrapper.dataset.status=visualStatus;

  const traffic = Number.isFinite(item.traffic) ? item.traffic : 0;
  wrapper.classList.toggle('is-traffic', item.status === 'up' && traffic > 0);
  wrapper.classList.toggle('is-busy', item.status === 'up' && traffic >= 10000000);

  const portNumber =
    Number((item.name.match(/\d+/) || [0])[0]) +
    (/^x/i.test(item.name) ? 24 : 0);

  wrapper.style.setProperty('--port-delay', ((portNumber % 8) * 0.11) + 's');

  const frame=wrapper.querySelector('.eth-frame');
  if(frame){
    frame.classList.remove('up','down','critical','disabled','unknown','management');
    frame.classList.add(visualStatus);
  }

  const label =
    visualStatus === 'critical' ? 'CRÍTICO' :
    visualStatus === 'unknown' ? 'N/D' :
    visualStatus.toUpperCase();

  wrapper.title=`${item.name} • ${label} • ${item.alias||'—'} • IN ${formatBps(item.input)} • OUT ${formatBps(item.output)}`;
}
