function aggregateSelected(map, names, maxPoints=120){
  const usable=names.map(n=>map.get(n)).filter(Boolean).map(frame=>({values:valuesOf(frame).map(v=>parseNumeric(v,null)),times:timesOf(frame)})).filter(e=>e.values.some(Number.isFinite));
  if(!usable.length)return {values:[],times:[]};
  const longest=usable.reduce((a,b)=>b.values.length>a.values.length?b:a,usable[0]);
  const len=Math.min(Math.max(...usable.map(e=>e.values.length)),maxPoints);
  const values=[],times=[];
  for(let p=0;p<len;p++){
    let sum=0,has=false;
    for(const e of usable){const idx=e.values.length-len+p;const v=idx>=0?e.values[idx]:null;if(Number.isFinite(v)){sum+=v;has=true;}}
    values.push(has?sum:0);
    const ti=longest.times.length-len+p; times.push(ti>=0?longest.times[ti]:null);
  }
  return {values,times};
}
