function renderTraffic(inValues,outValues,times){
  const width=1000,height=240,n=Math.max(inValues.length,outValues.length);
  if(!n){q('traffic-in-line')?.setAttribute('points','');q('traffic-out-line')?.setAttribute('points','');return;}
  const maximum=Math.max(1,...inValues,...outValues);
  const pts=(arr)=>arr.map((v,i)=>[i/Math.max(1,n-1)*width,height-(v||0)/maximum*height]);
  const poly=p=>p.map(x=>`${x[0]},${x[1]}`).join(' ');
  const area=p=>p.length?`M 0 ${height} L ${p.map(x=>`${x[0]} ${x[1]}`).join(' L ')} L ${width} ${height} Z`:'';
  const ip=pts(inValues),op=pts(outValues);
  q('traffic-in-line')?.setAttribute('points',poly(ip)); q('traffic-out-line')?.setAttribute('points',poly(op));
  q('traffic-in-area')?.setAttribute('d',area(ip)); q('traffic-out-area')?.setAttribute('d',area(op));
  const steps=[maximum,maximum*.75,maximum*.5,maximum*.25,0];
  root.querySelectorAll('.traffic-total-panel .axis-y').forEach((el,i)=>el.textContent=formatBps(steps[i]));
  if(times.length){const labels=root.querySelectorAll('.axis-x span');labels.forEach((el,i)=>{const idx=Math.round(i*(times.length-1)/Math.max(1,labels.length-1));const dt=new Date(times[idx]);el.textContent=Number.isNaN(dt.getTime())?'—':dt.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});});}
}
