/* V6.5.23 — tabela de interfaces refinada e alinhada ao Zabbix */

function interfaceSortRank(item){
  const n=String(item.name||'').toLowerCase();
  if(/^port\d+$/.test(n)) return 10;
  if(/^x\d+$/.test(n)) return 20;
  if(/^mgmt$/.test(n)) return 30;
  if(/^ha$/.test(n)) return 40;
  if(/^lacp_/.test(n)) return 50;
  if(/^vlan_/.test(n)) return 60;
  if(/vpn|spoke|tunnel/.test(n)) return 70;
  if(/loopback/.test(n)) return 80;
  return 90;
}

function naturalInterfaceName(name){
  return String(name||'').toLowerCase().replace(/(\d+)/g,m=>m.padStart(6,'0'));
}

function tableVisualState(item){
  const physicalName=String(item.name||'').toLowerCase();
  if(
    item.status==='down' &&
    typeof criticalPhysicalPorts!=='undefined' &&
    criticalPhysicalPorts.has(physicalName)
  ){
    return 'critical';
  }
  return item.status==='management'
    ? 'management'
    : item.status==='up'
      ? 'up'
      : item.status==='down'
        ? 'down'
        : 'unknown';
}

const displayInterfaces=interfaces.slice().sort((a,b)=>{
  const rank=interfaceSortRank(a)-interfaceSortRank(b);
  if(rank!==0) return rank;

  const an=naturalInterfaceName(a.name);
  const bn=naturalInterfaceName(b.name);
  return an.localeCompare(bn,'pt-BR',{numeric:true,sensitivity:'base'});
});

const rowsPerPage=13;
const totalPages=Math.max(1,Math.ceil(displayInterfaces.length/rowsPerPage));
const currentPage=totalPages>1?Math.floor(Date.now()/30000)%totalPages:0;
const visibleInterfaces=displayInterfaces.slice(
  currentPage*rowsPerPage,
  (currentPage+1)*rowsPerPage
);

const tableBody=q('interfaces-body');
if(tableBody){
  tableBody.innerHTML='';

  for(const item of visibleInterfaces){
    const row=doc.createElement('tr');

    const visualState=tableVisualState(item);
    const statusLabel=
      visualState==='management' ? 'MGMT' :
      visualState==='critical' ? 'CRÍTICO' :
      visualState==='unknown' ? 'N/D' :
      visualState.toUpperCase();

    const errorClass=
      Number.isFinite(item.errors) && item.errors>0
        ? 'error-bad'
        : 'error-ok';

    const isDown=item.status==='down';
    const util=
      !isDown && Number.isFinite(item.util)
        ? Math.max(0,Math.min(100,item.util))
        : 0;

    const speedText=
      isDown
        ? '—'
        : Number.isFinite(item.speed)
          ? formatBps(item.speed)
          : '—';

    const utilText=
      isDown
        ? '—'
        : Number.isFinite(item.util)
          ? `${formatNumber(item.util,1)}%`
          : '—';

    row.className=`interface-row status-${visualState}`;

    row.innerHTML=`
      <td class="left">${escapeHtml(item.name)}</td>
      <td class="center">
        <span class="table-status ${visualState}">${statusLabel}</span>
      </td>
      <td class="center interface-type">${escapeHtml(item.type)}</td>
      <td class="left alias-cell">${escapeHtml(item.alias)}</td>
      <td class="center">${speedText}</td>
      <td class="center">${formatBps(item.input)}</td>
      <td class="center">${formatBps(item.output)}</td>
      <td class="center">${Number.isFinite(item.discards)?formatNumber(item.discards,2):'—'}</td>
      <td class="center ${errorClass}">${Number.isFinite(item.errors)?formatNumber(item.errors,2):'—'}</td>
      <td class="center">
        <div class="util-cell">
          <span>${utilText}</span>
          <span class="util-bar"><i style="width:${util}%"></i></span>
        </div>
      </td>`;

    tableBody.appendChild(row);
  }
}

const tableMeta=root.querySelector('.table-panel .panel-meta');
if(tableMeta){
  tableMeta.textContent=
    `${interfaces.length} monitoradas • ${upPhysical} físicas UP • página ${currentPage+1}/${totalPages} • próxima no refresh`;
}

setText('prop-model',model || 'Fortinet FortiGate 200F');
setText('prop-hostname',hostName || 'LAB-FGT-01');
setText('prop-serial',serial && serial!=='—' ? serial : 'DEMO-FGT-SERIAL-01');
setText('prop-serial-ha2','DEMO-FGT-SERIAL-02');
setText('prop-software',firmware && firmware!=='—' ? firmware : 'v7.2.11 build1740 (GA.M)');
setText('prop-location',location);
setText('prop-description',systemDescription && systemDescription!=='—' ? systemDescription : 'Fortinet Firewall FortiGate-200F');
let haText='—';
if(ha1State.known || ha2State.known){
  if(ha1State.known && ha2State.known && ha1State.synced && ha2State.synced){
    haText='2/2 sincronizados';
  }else{
    haText=`HA1 ${ha1State.label} • HA2 ${ha2State.label}`;
  }
}else{
  haText=[haModeRaw,haSyncRaw].filter(v=>v&&v!=='—').join(' • ')||'—';
}

setText('prop-ha',haText);

const propHa=q('prop-ha');
if(propHa){
  propHa.classList.remove('healthy','warning','critical','unknown');

  if(ha1State.known && ha2State.known){
    if(ha1State.synced && ha2State.synced) propHa.classList.add('healthy');
    else propHa.classList.add('critical');
  }else if(ha1State.known || ha2State.known){
    propHa.classList.add('warning');
  }else{
    propHa.classList.add('unknown');
  }
}



